from pathlib import Path
p=Path(__file__).with_name('index.html')
s=p.read_text(encoding='utf-8')
css='''
:root{color-scheme:dark;--bg:#121416;--panel:#1c1f22;--line:#303438;--muted:#8e969e;--accent:#9be1cf}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#e9ecef;font:13px system-ui,"Microsoft YaHei",sans-serif}button,input,textarea,select{font:inherit}button{cursor:pointer}header{height:62px;padding:0 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center;background:#191c1f}.brand{display:flex;align-items:center;gap:14px}h1{font-size:16px;letter-spacing:.4px;margin:0;font-weight:650}.brand small{border-left:1px solid #454a4f;padding-left:14px;color:var(--muted);font-size:11px;letter-spacing:2px}.badge{font-size:12px;color:var(--accent)}main{margin:0 0 0 188px;padding:0;max-width:none}.sidebar{position:fixed;left:0;top:62px;bottom:0;width:188px;background:#191c1f;border-right:1px solid var(--line);padding:25px 12px;display:flex;flex-direction:column}.sidebar-label{font-size:10px;letter-spacing:2px;color:#707a83;margin:0 12px 16px}.tabs{display:flex;flex-direction:column;gap:7px}.tab{position:relative;text-align:left;background:transparent;border:1px solid transparent;border-radius:7px;padding:14px 12px;color:#bac2c9}.tab b{display:block;font-size:13px;font-weight:550;padding-left:24px}.tab b:before{content:'◇';position:absolute;left:12px;color:#859098;font-size:16px;top:10px}.tab:nth-child(2) b:before{content:'◎'}.tab:nth-child(3) b:before{content:'✎'}.tab:nth-child(4) b:before{content:'⌗'}.tab span{display:none}.tab:hover{background:#24292d}.tab.active{color:#c7f2e5;background:#253c35;border-color:#3c5d52}.tab.active b:before{color:var(--accent)}.sidebar-foot{margin-top:auto;padding:15px 12px;color:#747e87;font-size:11px;line-height:1.9}.sidebar-foot strong{font-weight:500;color:#adb8c0}.layout{display:grid;grid-template-columns:minmax(0,1fr) 336px;gap:0;min-height:calc(100vh - 252px)}.panel{padding:0;min-width:0}.settings{grid-column:2;grid-row:1;background:var(--panel);border-left:1px solid var(--line)}.settings-title{height:52px;display:flex;align-items:center;padding:0 22px;border-bottom:1px solid var(--line);font-size:13px;font-weight:600}.settings-title span{margin-left:auto;color:#6e7b84;font-size:10px;font-weight:400;letter-spacing:1px}form{padding:22px;max-height:calc(100vh - 285px);min-height:440px;overflow-y:auto}.canvas-panel{grid-column:1;grid-row:1;display:flex;flex-direction:column;padding:0 22px 16px}.toolbar{height:52px;display:flex;justify-content:space-between;align-items:center;gap:12px}.toolbar h3{font-size:12px;font-weight:500;color:#a5afb7;margin:0}.actions{display:flex;gap:8px}.secondary,.actions a{border:1px solid #3b4349;padding:6px 10px;border-radius:5px;background:#202529;color:#d2dedc;text-decoration:none;font-size:11px}.actions a{color:var(--accent)}.preview{flex:1;min-height:400px;max-height:calc(100vh - 330px);display:flex;align-items:center;justify-content:center;border:1px solid #2c3136;border-radius:6px;overflow:hidden;background-color:#15191b;background-image:linear-gradient(45deg,#191d20 25%,transparent 25%),linear-gradient(-45deg,#191d20 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#191d20 75%),linear-gradient(-45deg,transparent 75%,#191d20 75%);background-size:24px 24px;background-position:0 0,0 12px,12px -12px,-12px 0}.preview img{width:100%;height:100%;max-height:calc(100vh - 332px);object-fit:contain;filter:drop-shadow(0 8px 20px #0008)}.empty{text-align:center;padding:40px;color:#88959e}.symbol{width:68px;height:68px;margin:0 auto 20px;border:1px solid #414e57;border-radius:15px;display:grid;place-items:center;font-size:32px;color:#92b3ac;background:#222b2c}.help{font-size:11px;line-height:1.7;color:var(--muted);margin-top:8px}.muted{color:var(--muted)}label{display:block;margin-bottom:9px;font-size:12px;color:#c2c9ce}.field{margin-bottom:19px}textarea,input,select{width:100%;background:#15191c;border:1px solid #383e44;border-radius:5px;color:#edf0f2;padding:10px;outline:none}textarea:focus,input:focus,select:focus{border-color:#729f93}textarea{min-height:150px;resize:vertical;line-height:1.7;font-size:12px}.row{display:flex;gap:12px}.row>.field{flex:1}.upload{padding:16px;border:1px dashed #4a565e;text-align:center;border-radius:6px;background:#171c1f;cursor:pointer;font-size:12px;color:#a9b7c0}.upload input{display:none}.upload img{display:block;max-width:100%;max-height:160px;object-fit:contain;margin:12px auto 0;border-radius:4px}.primary{width:100%;border:1px solid #b3e5d5;background:var(--accent);color:#142f27;border-radius:6px;padding:12px;font-weight:650}.primary:disabled{opacity:.45;cursor:wait}.error{font-size:12px;color:#ffb6ae;line-height:1.6;white-space:pre-wrap;margin-top:10px}.statusline{font-size:11px;color:#92a49e;margin-top:12px;min-height:17px;max-width:100%;overflow-wrap:anywhere}progress{width:100%;height:4px;accent-color:var(--accent);margin-top:8px}.history{border-top:1px solid var(--line);background:#181c1f;padding:14px 22px 17px}.history h3{font-size:12px;font-weight:550;margin:0 0 12px;color:#c4cdd4}.history-grid{display:flex;gap:10px;overflow-x:auto;padding-bottom:4px;min-height:110px}.history-grid:empty:after{content:'还没有作品。完成的图片会保留在这里。';font-size:12px;color:#78858f;align-self:center}.history-card{flex:0 0 160px;display:flex;flex-direction:column;border:1px solid #343d43;border-radius:6px;background:#20262a;text-align:left;padding:0;overflow:hidden;color:#c6d0d6}.history-card:hover{border-color:#7da99b}.history-card img{width:100%;height:80px;object-fit:cover}.history-card .placeholder{height:80px;display:grid;place-items:center;font-size:11px;color:#8d9a9f}.meta{font-size:10px;line-height:1.7;padding:6px 8px;white-space:pre-line}.history-card.active{border-color:var(--accent)}footer{display:none}[hidden]{display:none!important}::-webkit-scrollbar{width:6px;height:6px}::-webkit-scrollbar-thumb{background:#3c464d;border-radius:4px}@media(min-width:1600px){.layout{grid-template-columns:minmax(0,1fr) 380px}form{padding:26px}}@media(max-width:1050px){.sidebar{width:148px;padding:20px 8px}main{margin-left:148px}.layout{grid-template-columns:minmax(0,1fr) 300px}.canvas-panel{padding:0 14px 14px}form{padding:18px}.tab b{font-size:12px}.brand small{display:none}}@media(max-width:760px){header{padding:0 16px}.sidebar{position:static;width:auto;padding:10px;border-bottom:1px solid var(--line);border-right:0}.sidebar-label,.sidebar-foot{display:none}.tabs{flex-direction:row;gap:4px}.tab{flex:1;padding:10px 5px;text-align:center}.tab b{padding-left:0;font-size:11px}.tab b:before{display:none}main{margin-left:0}.layout{display:flex;flex-direction:column}.canvas-panel{order:0}.settings{order:1;border-left:0;border-top:1px solid var(--line)}form{max-height:none;min-height:0}.preview{min-height:340px;max-height:500px}.preview img{max-height:500px}.history{padding:14px}.settings-title{height:44px}.badge{font-size:10px}}
'''
start=s.index('<style>');end=s.index('</style>',start)
s=s[:start]+'<style>'+css+s[end:]
s=s.replace('<header><div class="brand"><h1>◉ 蓝鲸 · 图像工作室</h1><small>LOCAL IMAGE STUDIO</small></div>', '<header><div class="brand"><h1>◉ 蓝鲸工作台</h1><small>IMAGE WORKSPACE</small></div>')
start=s.index('<main><div class="intro">');end=s.index('<div class="layout">',start)
s=s[:start]+'<aside class="sidebar"><div class="sidebar-label">创作工具</div><nav class="tabs" id="tabs"></nav><div class="sidebar-foot"><strong>本地工作空间</strong><br>Qwen Image 2.1<br>RTX 5070 · 12GB</div></aside><main>'+s[end:]
s=s.replace('<section class="panel"><form id="form">','<section class="panel settings"><div class="settings-title"><b id="tool-title">文字生图</b><span>PARAMETERS</span></div><form id="form">')
s=s.replace('<section class="panel"><div class="toolbar"><h3>生成结果</h3>','<section class="panel canvas-panel"><div class="toolbar"><h3>画布 / 生成结果</h3>')
s=s.replace('你的下一张作品，会出现在这里。','画布已就绪')
s=s.replace('生成完成后可下载原图、复用参数。','在右侧设置参数，开始你的第一张作品。')
s=s.replace('<h3>最近作品 ', '<h3>作品记录 ')
s=s.replace("mode=id;document.querySelectorAll", "mode=id;$('tool-title').textContent=tools.find(t=>t[0]===id)[1];document.querySelectorAll")
p.write_text(s,encoding='utf-8')
print('Workbench layout applied')
